/* Pretend this is the next release of @nysds/styles. */
:root {
  --nys-font-family-ui: var(--nys-font-family-serif);
  --nys-radius-xl: var(--nys-radius-round);
}

nys-card { width: 20rem; }
.stat { display: grid; margin: 0; }
.stat strong { display: block; line-height: 1.1; }

/* The card is the system's. What you slot into it is yours. */

/* What the guidance asks for */
.stat--tokens {
  gap: var(--nys-space-100);
  padding: var(--nys-space-300);
  border-left: var(--nys-border-width-md) solid var(--nys-color-theme);
  background: var(--nys-color-theme-faint);
  font-family: var(--nys-font-family-ui);
  color: var(--nys-color-text);
}
.stat--tokens strong {
  font-size: var(--nys-font-size-h2);
  font-weight: var(--nys-font-weight-bold);
}
.stat--tokens span {
  font-size: var(--nys-font-size-body-sm);
  color: var(--nys-color-text-weak);
}

/* What the guidance can't prevent */
.stat--hardcoded {
  gap: 0.5rem;
  padding: 1.5rem;
  border-left: 2px solid #154973;
  background: #f7fafd;
  font-family: "Proxima Nova", Arial, sans-serif;
  color: #1b1b1b;
}
.stat--hardcoded strong {
  font-size: 2rem;
  font-weight: 700;
}
.stat--hardcoded span {
  font-size: 0.875rem;
  color: #4a4d4f;
}

/* Uncomment to "release" a system change:
:root {
  --nys-font-family-ui: var(--nys-font-family-serif);
  --nys-color-theme: var(--nys-color-danger);
}
*/

.levels { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--nys-space-600); align-items: start; }
.levels section { display: grid; gap: var(--nys-space-300); }
.caption { font: var(--nys-font-weight-semibold) var(--nys-font-size-ui-lg) var(--nys-font-family-ui); color: var(--nys-color-text); margin: 0; }
.caption.is-dim { opacity: 0.35; }
.doc { padding: var(--nys-space-400); border: var(--nys-border-width-sm) solid var(--nys-color-neutral-300); border-radius: var(--nys-radius-xl); background: var(--nys-color-surface); font-family: var(--nys-font-family-monospace); font-size: var(--nys-font-size-sm); margin: 0; }
.danger {
  --nys-button-background-color: var(--nys-color-danger);
  --nys-button-background-color--hover: var(--nys-color-danger-strong);
  --nys-button-background-color--active: var(--nys-color-danger-strongest);
}

presets.js:
// Press Space to reveal captions one at a time.
const captions = [...document.querySelectorAll('.caption')];
captions.forEach(c => c.classList.add('is-dim'));
let i = 0;
document.addEventListener('keydown', (e) => {
  if (e.code !== 'Space') return;
  e.preventDefault();
  if (captions[i]) captions[i].classList.remove('is-dim');
  i += 1;
});

presets.css:
.spectrum { position: relative; margin: 4rem 0 0; padding: 0 2rem; font-family: var(--nys-font-family-ui); }
.line { height: var(--nys-border-width-md); background: var(--nys-color-neutral-400); border-radius: var(--nys-radius-round); }
.spectrum ol { list-style: none; margin: 0; padding: 0; position: relative; height: 5rem; }
.spectrum li { position: absolute; left: var(--x); top: 0; transform: translateX(-50%); text-align: center; display: grid; gap: var(--nys-space-100); }
.spectrum li::before { content: ''; width: 1rem; height: 1rem; border-radius: var(--nys-radius-round); background: var(--nys-color-theme); justify-self: center; margin-top: -0.6rem; }
.spectrum span { font-weight: var(--nys-font-weight-bold); font-size: var(--nys-font-size-ui-xl); }
.spectrum small { color: var(--nys-color-text-weak); font-family: var(--nys-font-family-monospace); }
figcaption { margin-top: var(--nys-space-800); text-align: center; font-size: var(--nys-font-size-h4); color: var(--nys-color-text); }
